 private const string Owner="fixture:neifa-owner",Driver="fixture:neifa-driver",Quiet="fixture:neifa-quiet",Watch="fixture:neifa-watch",Mode="identity:classic-neifa";
 private static string Branch(PromptChoice c)=>c.Parameters.GetValueOrDefault("branch")??"";
 private static bool Optional(GameEngine g)=>P(g)?.SkillPrompt?.SkillId=="ol:neifa"&&P(g)!.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="activate");
 private static void Arm(GameEngine g,bool basic){Reach(g,()=>Optional(g));Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="activate");Answer(g,c=>Branch(c)=="draw");Reach(g,()=>g.ResolutionStack.OfType<ProgramSkillFrame>().LastOrDefault()?.Neifa?.Stage==NeifaStage.Discard);Answer(g,c=>c.Cards.Count==1&&(CardCatalog.Get(V(g,0).Hand.Concat(V(g,0).Equipment).Single(x=>x.Id==c.Cards[0]).Kind).CategoryName=="基本牌")==basic);Play(g);}
 public static void BasicDiscardDynamicSlashQuotaTwoTargetsAndTurnExpiryCold()
 {
  var(g,r)=Start();Arm(g,true);Need(E<NeifaTurnArmedEvent>(g).Single().BasicBranch,"Actual basic discard establishes the issued basic branch.");
  Need(g.GetHumanLegalActions().Where(a=>a.CardId is not null).All(a=>V(g,0).Hand.Single(c=>c.Id==a.CardId).Kind is CardKind.Slash or CardKind.Dodge or CardKind.Peach or CardKind.Alcohol),"Actual effective trick/equipment use actions are prohibited after the real cost.");
  var slash=g.GetHumanLegalActions().First(a=>a.Kind==LegalActionKind.Slash&&a.TargetSeats.Count==2);g=Cold(g,r);Native(g,slash);Play(g);Need(E<CardActionAcceptedEvent>(g).Any(e=>e.Action.EffectiveKind==CardKind.Slash&&e.Action.TargetSeats.Count==2),"The existing native Slash accepts two actual targets without changing its kind or actor.");Need(g.GetHumanLegalActions().Any(a=>a.Kind==LegalActionKind.Slash),"Dynamic X grants another ordinary counted Slash after the first actual use.");End(g);Reach(g,()=>Optional(g));Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="skip");Play(g);Need(g.GetHumanLegalActions().Any(a=>a.Kind==LegalActionKind.Duel),"The old actual-turn category prohibition expires before the next own Play.");_=Cold(g,r);
 }
 private static void Native(GameEngine g,LegalAction a)=>Accept(g,new PlayCardCommand(0,a.CardId!.Value,a.TargetSeats,g.Revision,P(g)!.PromptId,a.PlayedCardKind,a.TargetCardId){ConversionSource=a.ConversionSource});
    private static IEnumerable<T>E<T>(GameEngine g)where T:IGameEvent=>g.Events.Select(e=>e.Payload).OfType<T>();private static PlayerSnapshot V(GameEngine g,int s)=>g.CreateSnapshot(s).Players[s];private static PendingDecision?P(GameEngine g)=>Enumerable.Range(0,4).Select(s=>g.CreateSnapshot(s).PendingDecision).FirstOrDefault(p=>p!=null);
    private static void Need(bool b,string m){if(!b)throw new InvalidOperationException(m);}private static void Accept(GameEngine g,GameCommand c){var x=g.Submit(CommandJson.Deserialize(CommandJson.Serialize([c])).Single());Need(x.Accepted,(x.Error?.Message??"Rejected Neifa command.")+" "+Diagnostic(g));}private static void Answer(GameEngine g,Func<PromptChoice,bool>test){var p=P(g)!;Accept(g,new AnswerPromptCommand(p.PlayerSeat,p.PromptId,p.Choices.First(test).Id,g.Revision));}
private static void End(GameEngine g)=>Accept(g,new EndPlayPhaseCommand(0,g.Revision,P(g)!.PromptId));
    private static void Play(GameEngine g)=>Reach(g,()=>P(g)is{PlayerSeat:0,Kind:DecisionKind.PlayCard});
    private static void Reach(GameEngine g,Func<bool>done){for(var i=0;i<200;i++){if(done())return;var p=P(g);if(p?.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="skip")==true)Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="skip");else if(p is{Kind:DecisionKind.RescueDying,PlayerSeat:0})Answer(g,c=>c.Parameters.GetValueOrDefault("response")=="let-die");else if(p is{PlayerSeat:0,Kind:DecisionKind.PlayCard})End(g);else if(p is{PlayerSeat:0,Kind:DecisionKind.Nullification or DecisionKind.RespondSlash or DecisionKind.RespondDodge})Answer(g,c=>c.Parameters.GetValueOrDefault("response") is "pass" or "take-damage");else Accept(g,new AdvanceOneStepCommand(g.Revision));}throw new InvalidOperationException("Small native Neifa fixture exceeded its boundary. "+Diagnostic(g));}
    private static string Diagnostic(GameEngine g)=>System.Text.Json.JsonSerializer.Serialize(new{Pending=P(g)is{}p?new{p.Kind,p.PlayerSeat,Skill=p.SkillPrompt?.SkillId,Choices=p.Choices.Select(c=>new{c.Id,c.Label})}:null,Frames=g.ResolutionStack.Select(f=>new{Type=f.GetType().Name,f.Id,f.Step}),LastEventTypes=g.Events.TakeLast(12).Select(e=>e.Payload.GetType().Name)});
    private static string State(GameEngine g)=>System.Text.Json.JsonSerializer.Serialize(new{Views=Enumerable.Range(0,4).Select(s=>SnapshotJson.Serialize(g.CreateSnapshot(s))),Frames=g.ResolutionStack.Select(f=>System.Text.Json.JsonSerializer.Serialize(f,f.GetType())),Commands=CommandJson.Serialize(g.AcceptedCommands)});private static GameEngine Cold(GameEngine g,ContentRegistry r){var restored=GameReplay.Restore(GameCheckpointJson.Deserialize(GameCheckpointJson.Serialize(g.CreateCheckpoint())),r);Need(State(g)==State(restored),"Every private viewer, exact acquired lease/debt and once-paid native child survives cold replay.");return restored;}

 private static (GameEngine,ContentRegistry)Start(CardKind kind=CardKind.Duel,bool watch=false,bool death=false,bool equipmentWatch=false,bool falu=false,bool lion=false,bool extraPlay=false)
 {
  var r=ContentRegistry.Build(new StandardContentPackage(),new Fixture(kind,watch,death,equipmentWatch,falu,lion,extraPlay));var g=GameEngine.CreateStandard(new GameOptions{Seed=7,PlayerCount=4,HumanSeat=0,HumanRole=watch?Role.Rebel:Role.Lord,ModeId=Mode,UseInteractiveSetup=true,UseInteractiveDiscard=false,AdvanceAfterHumanCommands=false,MaxTurns=12},r);Accept(g,new StartGameCommand());Reach(g,()=>P(g)is{PlayerSeat:0,Kind:DecisionKind.SelectGeneral});Accept(g,new SelectGeneralCommand(0,Owner,g.Revision,P(g)!.PromptId));return(g,r);
 }
